/// Source templates emitted by the make:* commands.
library;

/// Render a model class skeleton named [className] for [table].
String modelTemplate({required String className, required String table}) =>
    '''
import 'package:worm/worm.dart';

/// Generated by `worm make:model`.
@Table(name: '$table')
final class $className extends Model {
  /// Default constructor.
  $className();

  /// Primary key.
  late final String id;
}
''';

/// Render a migration class skeleton named [className] for [table].
String migrationTemplate({
  required String className,
  required String table,
  required String fileName,
}) =>
    '''
import 'package:worm/worm.dart';

/// Generated by `worm make:migration`.
final class $className extends Migration {
  /// Default constructor.
  const $className();

  @override
  String get name => '$fileName';

  @override
  Future<void> upSchema(Schema schema) async {
    await schema.create('$table', (table) {
      table.idUuid();
    });
  }

  @override
  Future<void> downSchema(Schema schema) async {
    await schema.drop('$table', ifExists: true);
  }
}
''';

/// Render a seeder skeleton named [className] for [table].
String seederTemplate({required String className, required String table}) =>
    '''
import 'package:worm/worm.dart';

/// Generated by `worm make:seeder`.
final class $className extends Seeder {
  /// Default constructor.
  const $className();

  @override
  String get name => '$className';

  @override
  Future<void> run(DatabaseAdapter adapter) async {
    // TODO: insert seed rows into "$table".
  }
}
''';

/// Render a factory skeleton for [modelClass].
String factoryTemplate({
  required String className,
  required String modelClass,
}) =>
    '''
import 'package:worm/worm.dart';

/// Generated by `worm make:factory`.
final class $className extends Factory<$modelClass> {
  /// Default constructor.
  const $className();

  @override
  $modelClass definition() => $modelClass();
}
''';

/// Render an observer skeleton named [className] bound to [modelClass].
String observerTemplate({
  required String className,
  required String modelClass,
}) =>
    '''
import 'package:worm/worm.dart';

/// Generated by `worm make:observer`.
final class $className extends Observer<$modelClass> {
  /// Default constructor.
  const $className();
}
''';

/// Render the worm.yaml-style entry file written by `worm init`.
String initReadme() => '''
# worm

This directory was scaffolded by `worm init`.

Subdirectories:

- `migrations/` — schema migrations
- `seeds/`      — database seeders
- `factories/`  — model factories for tests
- `models/`     — domain models
''';
